import{_ as e,o as r,c as a,a2 as d}from"./chunks/framework.D9DTPhg1.js";const u=JSON.parse('{"title":"Benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks.md","filePath":"website/benchmarks.md"}'),s={name:"benchmarks.md"};function o(i,t,n,h,l,c){return r(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#benchmarks" aria-label="Permalink to &quot;Benchmarks&quot;">​</a></h1><p>Prism is measured against Doctrine ORM 3 on four scenarios: hydration, flush, the N+1 pattern and a long-running worker. Every figure is published, including those where Doctrine is faster. The code, the method and the raw results are in <a href="https://github.com/prism-orm/prism/tree/main/tools/bench/doctrine" target="_blank" rel="noreferrer"><code>tools/bench/doctrine</code></a> (<a href="https://github.com/prism-orm/prism/blob/main/tools/bench/doctrine/RESULTS.md" target="_blank" rel="noreferrer">results</a>).</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Result</th></tr></thead><tbody><tr><td>N+1: 100 orders, their customer and their lines</td><td>Prism 4.4 to 5.6 times faster than Doctrine by default, 3 queries instead of 168; on par with a join written by hand</td></tr><tr><td>Flush of 1,000 UPDATE</td><td>Prism 5 % faster under MySQL, 17 % under PostgreSQL</td></tr><tr><td>Flush of 1,000 INSERT</td><td>Doctrine 15 % faster under MySQL, equal under PostgreSQL</td></tr><tr><td>Hydration of 10,000 entities</td><td>Doctrine 6 to 10 % faster, with about 15 % less memory</td></tr><tr><td>Worker, one write per request</td><td>Doctrine 1.9 times faster under MySQL, Prism 1.4 times faster under PostgreSQL; no memory growth on either side</td></tr></tbody></table><h2 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Method&quot;">​</a></h2><ul><li><strong>Same conditions</strong>: same PHP process settings, same database, same tables and same data, created from a fixed seed. Both ORMs map the entities with attributes, cache their metadata, use PHP 8.4 native lazy objects, and run without SQL logger, profiler or second-level cache.</li><li><strong>Same entities</strong>: each entity is written twice, once per ORM, with the same fields and types; a <code>decimal</code> is a string on both sides.</li><li><strong>Durations</strong> are measured by PHPBench: median of 10 iterations, after a warm-up. <strong>Memory</strong> is read with <code>memory_get_usage()</code> inside the scenario process.</li><li><strong>Machine</strong>: Intel Xeon Gold 5218 (8 cores available), 7.7 GB, PHP 8.4.27 CLI with opcache and without JIT, MySQL 8.4 and PostgreSQL 16 in Docker on the same host. Doctrine ORM 3.7.5 with DBAL 4.5.0. The host is not dedicated: a figure can move by 10 to 20 % from one run to another.</li></ul><p>To run them again, from a clone of the repository:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench-doctrine</span></span></code></pre></div><h2 id="n-1" tabindex="-1">N+1 <a class="header-anchor" href="#n-1" aria-label="Permalink to &quot;N+1&quot;">​</a></h2><p>100 orders are read, then the customer (ManyToOne) and the lines (OneToMany) of each one. Times in milliseconds.</p><table tabindex="0"><thead><tr><th></th><th>MySQL</th><th>PostgreSQL</th><th>Queries</th></tr></thead><tbody><tr><td>Prism, default</td><td>21.9</td><td>18.3</td><td>3</td></tr><tr><td>Doctrine, default</td><td>97.0</td><td>103.1</td><td>168</td></tr><tr><td>Doctrine, hand-written join</td><td>21.9</td><td>18.6</td><td>1</td></tr></tbody></table><p>Prism loads the lazy relations of all the orders in one query per relation: see <a href="/prism/guide/n-plus-one">Avoiding N+1 queries</a>. Doctrine reaches the same time once the join is written by hand.</p><h2 id="flush" tabindex="-1">Flush <a class="header-anchor" href="#flush" aria-label="Permalink to &quot;Flush&quot;">​</a></h2><p>One <code>flush()</code> of 1,000 new entities, then one <code>flush()</code> after changing a field on 1,000 managed entities. Times in milliseconds.</p><table tabindex="0"><thead><tr><th></th><th>MySQL Prism</th><th>MySQL Doctrine</th><th>PostgreSQL Prism</th><th>PostgreSQL Doctrine</th></tr></thead><tbody><tr><td>1,000 INSERT</td><td>156.7</td><td>136.3</td><td>186.4</td><td>193.0</td></tr><tr><td>1,000 UPDATE</td><td>127.2</td><td>133.4</td><td>104.6</td><td>125.9</td></tr></tbody></table><h2 id="hydration" tabindex="-1">Hydration <a class="header-anchor" href="#hydration" aria-label="Permalink to &quot;Hydration&quot;">​</a></h2><p><code>findAll()</code> of 10,000 entities of a typical ERP row (text, amount, quantity, boolean, date), without relation.</p><table tabindex="0"><thead><tr><th></th><th>MySQL Prism</th><th>MySQL Doctrine</th><th>PostgreSQL Prism</th><th>PostgreSQL Doctrine</th></tr></thead><tbody><tr><td>Time</td><td>168.7 ms</td><td>152.0 ms</td><td>122.1 ms</td><td>115.0 ms</td></tr><tr><td>Peak memory</td><td>22.5 MB</td><td>19.6 MB</td><td>22.1 MB</td><td>19.1 MB</td></tr></tbody></table><p>Both ORMs read the rows one at a time. For each entity, Prism&#39;s unit of work keeps the values read and a smaller snapshot of the identifier, the version and the foreign keys, where Doctrine keeps one array.</p><h2 id="worker" tabindex="-1">Worker <a class="header-anchor" href="#worker" aria-label="Permalink to &quot;Worker&quot;">​</a></h2><p>10,000 requests in one process, as in a FrankenPHP or Messenger worker: each one reads 20 orders and their customer, changes the status of one, then calls <code>flush()</code> and <code>clear()</code>.</p><table tabindex="0"><thead><tr><th></th><th>MySQL Prism</th><th>MySQL Doctrine</th><th>PostgreSQL Prism</th><th>PostgreSQL Doctrine</th></tr></thead><tbody><tr><td>Throughput</td><td>184 req/s</td><td>345 req/s</td><td>381 req/s</td><td>264 req/s</td></tr><tr><td>Memory after 1,000 requests</td><td>1.95 MB</td><td>1.88 MB</td><td>1.91 MB</td><td>1.84 MB</td></tr><tr><td>Growth up to 10,000</td><td>0 KB</td><td>0 KB</td><td>0 KB</td><td>0 KB</td></tr></tbody></table><p>Neither ORM keeps anything from one request to the next. Under MySQL, Doctrine is ahead in this scenario; both ORMs send the same statements to the server, and the cause is being investigated before 1.0.</p><p>These figures date from 2026-10-29. They are measured again before 1.0, then at each minor version.</p>`,24)])])}const p=e(s,[["render",o]]);export{u as __pageData,p as default};
